def evaluate(current_reputation, observation, my_history, round_num):
    action = observation.get('action', 'defect')
    recent_window = observation.get('recent_window', [])

    if action == 'cooperate':
        change = 0.4
    else:
        change = -0.4

    if recent_window:
        coop_count = sum(1 for entry in recent_window if entry.get('action') == 'cooperate')
        recent_ratio = coop_count / max(len(recent_window), 1)
        change *= (0.3 + 0.7 * recent_ratio)

    decay = 1.0 / (1 + round_num * 0.01)
    new_reputation = current_reputation + change * decay
    return max(-1.0, min(1.0, new_reputation))

